select c.id cid, pr.code proj, d.unit_number, c.name cname, c.state, c.contract_date, c.handover_date, c.sale_price, c.booking_amount, c.total_paid, c.overall_payment_state, c.payment_schedule_id, p.name buyer, p.phone, p.email, (select count(*) from sale_contract_installment i where i.contract_id=c.id) n_inst, (select coalesce(sum(amount),0) from sale_contract_installment i where i.contract_id=c.id) inst_sum, (select coalesce(sum(amount),0) from sale_contract_installment i where i.contract_id=c.id and state='paid') inst_paid, replace(coalesce(c.notes,''),chr(10),' | ') notes from sale_contract c join property_details d on d.id=c.property_id join property_project pr on pr.id=d.project_id join res_partner p on p.id=c.buyer_id order by 2,3
